// Simple NLQ processor - handles basic patterns only
const query = msg.payload.query || "";
const q = query.toLowerCase();
const bucket = env.get("INFLUX_BUCKET") || "SS-Anthem";

let flux = "";
let summary = "";

// Pattern matching for simple queries
if (q.includes("scene event") || q.includes("scene_event") || q.includes("scene events")) {
    if (q.includes("last") && q.includes("hour")) {
        flux = `from(bucket:"${bucket}") |> range(start:-1h) |> filter(fn:(r)=> r._measurement == "scene_event")`;
        summary = "Showing scene events from the last hour.";
    } else if (q.includes("today")) {
        flux = `from(bucket:"${bucket}") |> range(start:-24h) |> filter(fn:(r)=> r._measurement == "scene_event")`;
        summary = "Showing scene events from today.";
    } else {
        flux = `from(bucket:"${bucket}") |> range(start:-24h) |> filter(fn:(r)=> r._measurement == "scene_event")`;
        summary = "Showing recent scene events.";
    }
} else if (q.includes("object") && q.includes("detect")) {
    if (q.includes("count")) {
        flux = `from(bucket:"${bucket}") |> range(start:-24h) |> filter(fn:(r)=> r._measurement == "object_detection") |> count()`;
        summary = "Counting object detections from the last 24 hours.";
    } else {
        flux = `from(bucket:"${bucket}") |> range(start:-24h) |> filter(fn:(r)=> r._measurement == "object_detection")`;
        summary = "Showing object detections from the last 24 hours.";
    }
} else if (q.includes("person") && q.includes("count")) {
    flux = `from(bucket:"${bucket}") |> range(start:-24h) |> filter(fn:(r)=> r._measurement == "scene_event" and r._field == "person_count")`;
    summary = "Showing person count data from the last 24 hours.";
} else if (q.includes("camera")) {
    // Extract camera name if possible
    const camMatch = q.match(/cam\d+/);
    const cam = camMatch ? camMatch[0] : "cam1";
    flux = `from(bucket:"${bucket}") |> range(start:-24h) |> filter(fn:(r)=> r.camera == "${cam}")`;
    summary = `Showing data from ${cam} for the last 24 hours.`;
} else {
    // Default fallback
    flux = `from(bucket:"${bucket}") |> range(start:-1h) |> limit(n:100)`;
    summary = "Showing recent data from the last hour (limited to 100 records).";
}

msg.payload = {
    success: true,
    flux_query: flux,
    summary: summary,
    original_query: query
};

return msg;
